const seedCars = [
{id:1,brand:"Porsche",name:"911 Carrera GTS",price:142000,power:480,accel:"3.0 с",speed:311,category:"sport",tag:"SPORT",year:2025,drive:"Полный",engine:"3.0 л",image:"data:image/jpeg;base64,",desc:"Легендарный силуэт, точная управляемость и характер, который раскрывается с каждым поворотом."},
{id:2,brand:"BMW",name:"M4 Competition",price:98000,power:510,accel:"3.5 с",speed:290,category:"sport",tag:"PERFORMANCE",year:2025,drive:"Задний",engine:"3.0 л",image:"data:image/jpeg;base64,",desc:"Спортивная ДНК M-серии в сочетании с современными технологиями и повседневным комфортом."},
{id:3,brand:"Mercedes-Benz",name:"S 580",price:125000,power:503,accel:"4.4 с",speed:250,category:"premium",tag:"LUXURY",year:2025,drive:"Полный",engine:"4.0 л",image:"data:image/jpeg;base64,",desc:"Флагманский комфорт, сдержанная сила и внимание к каждой детали интерьера."},
{id:4,brand:"Audi",name:"RS 7 Sportback",price:118000,power:600,accel:"3.6 с",speed:305,category:"sport",tag:"SPORT",year:2024,drive:"Полный",engine:"4.0 л",image:"data:image/jpeg;base64,",desc:"Гран-туризмо с мощным характером: динамика суперкара и практичность на каждый день."},
{id:5,brand:"Lamborghini",name:"Huracán EVO",price:280000,power:640,accel:"2.9 с",speed:325,category:"sport",tag:"EXCLUSIVE",year:2024,drive:"Полный",engine:"5.2 л",image:"data:image/jpeg;base64,",desc:"Эмоции без фильтров: атмосферный двигатель, выразительный дизайн и гоночная точность."},
{id:6,brand:"Range Rover",name:"Sport Autobiography",price:130000,power:530,accel:"4.3 с",speed:250,category:"suv",tag:"SUV",year:2025,drive:"Полный",engine:"4.4 л",image:"data:image/jpeg;base64,",desc:"Уверенность на любом маршруте, премиальный комфорт и внушительная мощность."}
];
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const money=n=>"$"+Math.round(n).toLocaleString("en-US");
const get=(k,d)=>{try{return JSON.parse(localStorage.getItem(k))??d}catch{return d}};
let cars=get("velocity-admin-cars",seedCars), favorites=get("velocity-favorites",[]), compare=[], filter="all", toastTimer, financePlan="credit";
function saveCars(){localStorage.setItem("velocity-admin-cars",JSON.stringify(cars))}
function toast(t){const e=$("#toast");e.textContent=t;e.classList.add("show");clearTimeout(toastTimer);toastTimer=setTimeout(()=>e.classList.remove("show"),2600)}
function card(c){return `<article class="car-card"><div class="car-image"><img src="${c.image||""}" alt="${c.brand} ${c.name}" loading="lazy" onerror="this.style.opacity='.12'"><span class="car-tag">${c.tag||"COLLECTION"}</span><button class="favorite-btn ${favorites.includes(c.id)?"is-favorite":""}" data-fav="${c.id}" aria-label="Избранное">${favorites.includes(c.id)?"♥":"♡"}</button></div><div class="car-info"><div class="car-brand">${c.brand} · ${c.year||2025}</div><h3>${c.name}</h3><div class="car-price">${money(c.price)} <small>USD</small></div><div class="car-specs"><span>${c.power} л.с.</span><span>${c.accel||"—"}</span></div><div class="card-actions"><button data-details="${c.id}">Подробнее ↗</button><button data-compare="${c.id}">${compare.includes(c.id)?"✓ В сравнении":"⇄ Сравнить"}</button></div></div></article>`}
function render(){
 const q=$("#searchInput").value.trim().toLowerCase(),brand=$("#brandFilter").value,max=+$("#priceRange").value,sort=$("#sortSelect").value;
 let list=cars.filter(c=>(filter==="all"||c.category===filter)&&(!q||(c.brand+" "+c.name).toLowerCase().includes(q))&&(brand==="all"||c.brand===brand)&&c.price<=max);
 if(sort==="low")list.sort((a,b)=>a.price-b.price);if(sort==="high")list.sort((a,b)=>b.price-a.price);if(sort==="power")list.sort((a,b)=>b.power-a.power);
 $("#carGrid").innerHTML=list.length?list.map(card).join(""):`<div class="empty-state">Ничего не найдено.<br><br><button class="button" id="clearSearch">Сбросить фильтры</button></div>`;
 $("#resultsCount").textContent=`Показано ${list.length} из ${cars.length} автомобилей`;$$("#brandFilter option").slice(1).forEach(o=>o.remove());
 [...new Set(cars.map(c=>c.brand))].sort().forEach(b=>{const o=document.createElement("option");o.value=b;o.textContent=b;$("#brandFilter").append(o)});
 if(brand!=="all")$("#brandFilter").value=brand;
 $("#priceLabel").textContent=max===300000?"до $300 000":`до ${money(max)}`;
 const select=$("#testdriveCar"),previous=select.value;select.innerHTML='<option value="">Пока выбираю</option>'+cars.map(c=>`<option>${c.brand} ${c.name}</option>`).join("");select.value=previous;
 renderCompare();
}
function renderCompare(){
 $("#compareCount").textContent=`${compare.length} ${compare.length===1?"автомобиль выбран":compare.length<5?"автомобиля выбрано":"автомобилей выбрано"}`;
 const selected=cars.filter(c=>compare.includes(c.id)),wrap=$("#compareTableWrap");
 if(!selected.length){wrap.innerHTML='<div class="compare-empty">Выберите автомобили в каталоге и нажмите <b>«Сравнить»</b>.</div>';return}
 const rows=[["Стоимость",c=>money(c.price)],["Мощность",c=>`${c.power} л.с.`],["Разгон 0–100 км/ч",c=>c.accel||"—"],["Максимальная скорость",c=>`${c.speed||"—"} км/ч`],["Двигатель",c=>c.engine||"—"],["Привод",c=>c.drive||"—"]];
 wrap.innerHTML=`<table class="compare-table"><thead><tr><th>Характеристика</th>${selected.map(c=>`<th><img src="${c.image||""}" alt=""><b>${c.brand} ${c.name}</b><br><button data-remove-compare="${c.id}">Убрать ×</button></th>`).join("")}</tr></thead><tbody>${rows.map(([l,f])=>`<tr><td>${l}</td>${selected.map(c=>`<td>${f(c)}</td>`).join("")}</tr>`).join("")}</tbody></table>`;
}
function showDetails(id){const c=cars.find(x=>x.id===+id);if(!c)return;$("#modalContent").innerHTML=`<img class="modal-car-image" src="${c.image||""}" alt="${c.name}" onerror="this.style.opacity='.15'"><div class="eyebrow">${c.brand.toUpperCase()} / ${c.year||2025} / ${c.tag||"COLLECTION"}</div><h2 id="modalTitle">${c.brand} ${c.name}</h2><p>${c.desc||"Премиальный автомобиль из коллекции VELOCITY."}</p><div class="modal-price">${money(c.price)} <small>USD</small></div><div class="modal-specs"><div><small>МОЩНОСТЬ</small><b>${c.power} л.с.</b></div><div><small>0–100 КМ/Ч</small><b>${c.accel||"—"}</b></div><div><small>МАКС. СКОРОСТЬ</small><b>${c.speed||"—"} км/ч</b></div><div><small>ДВИГАТЕЛЬ</small><b>${c.engine||"—"}</b></div><div><small>ПРИВОД</small><b>${c.drive||"—"}</b></div><div><small>ГОД</small><b>${c.year||2025}</b></div></div><button class="button" data-modal-testdrive="${c.id}">Записаться на тест-драйв <span>↗</span></button>`;openModal("modal")}
function openModal(id){$("#"+id).hidden=false;document.body.style.overflow="hidden"}
function closeModal(id){$("#"+id).hidden=true;document.body.style.overflow=""}
function calculate(){
 const cost=+$("#carCost").value,downPct=+$("#down").value,months=+$("#term").value,annual=+$("#rate").value/100,down=cost*downPct/100,principal=cost-down;
 $("#carCostLabel").textContent=money(cost);$("#downLabel").textContent=`${downPct}% · ${money(down)}`;$("#termLabel").textContent=`${months} месяцев`;$("#rateLabel").textContent=`${(annual*100).toFixed(1)}%`;
 let monthly;if(financePlan==="lease"){monthly=principal/months+cost*.012}else{const r=annual/12;monthly=r?principal*r/(1-Math.pow(1+r,-months)):principal/months}
 const total=monthly*months+down,overpay=Math.max(0,total-cost);
 $("#monthlyPayment").textContent=money(monthly);$("#resultDown").textContent=money(down);$("#resultPrincipal").textContent=money(principal);$("#resultOverpay").textContent=money(overpay);$("#resultTotal").textContent=money(total);
}
function renderAdmin(){
 $("#adminList").innerHTML=cars.map(c=>`<div class="admin-car-row"><span><b>${c.brand} ${c.name}</b><br><small>${money(c.price)} · ${c.power} л.с.</small></span><button data-admin-delete="${c.id}">Удалить</button></div>`).join("");
}
function galleryInit(){
 const photos=[
 ["Porsche 911 — timeless design","data:image/jpeg;base64,"],
 ["Performance in every line","data:image/jpeg;base64,"],
 ["A different kind of luxury","data:image/jpeg;base64,"],
 ["Made for the open road","data:image/jpeg;base64,"]];
 let i=0;const show=n=>{i=(n+photos.length)%photos.length;$("#galleryImage").style.opacity=".2";setTimeout(()=>{$("#galleryImage").src=photos[i][1];$("#galleryTitle").textContent=photos[i][0];$("#galleryCounter").textContent=`${String(i+1).padStart(2,"0")} / ${String(photos.length).padStart(2,"0")}`;$("#galleryImage").style.opacity="1";$$(".gallery-thumb").forEach((b,j)=>b.classList.toggle("selected",j===i))},130)};
 $("#galleryThumbs").innerHTML=photos.map((p,j)=>`<button class="gallery-thumb ${j===0?"selected":""}" data-gallery="${j}" aria-label="Фото ${j+1}"><img src="${p[1]}" alt=""></button>`).join("");
 $("#galleryPrev").onclick=()=>show(i-1);$("#galleryNext").onclick=()=>show(i+1);$("#galleryThumbs").onclick=e=>{const b=e.target.closest("[data-gallery]");if(b)show(+b.dataset.gallery)};
}
$("#filterTabs").addEventListener("click",e=>{const b=e.target.closest("[data-filter]");if(!b)return;if(b.dataset.filter==="all"){resetFilters();return}filter=b.dataset.filter;$$(".filter-tab").forEach(x=>x.classList.toggle("selected",x===b));render()});
["searchInput","brandFilter","priceRange","sortSelect"].forEach(id=>$("#"+id).addEventListener(id==="searchInput"?"input":"change",render));
function resetFilters(){
filter="all";$("#searchInput").value="";$("#brandFilter").value="all";$("#priceRange").value=300000;$("#sortSelect").value="featured";
$$(".filter-tab").forEach(b=>b.classList.toggle("selected",b.dataset.filter==="all"));render();
}
const resetButton=$("#resetFilters");if(resetButton)resetButton.addEventListener("click",resetFilters);
const showAllButton=$("#showAll");if(showAllButton)showAllButton.addEventListener("click",()=>{resetFilters();$("#catalog").scrollIntoView({behavior:"smooth"})});
$("#searchFocus").addEventListener("click",()=>{$("#catalog").scrollIntoView({behavior:"smooth"});setTimeout(()=>$("#searchInput").focus(),500)});
document.addEventListener("click",e=>{
 let b=e.target.closest("[data-fav]");if(b){const id=+b.dataset.fav;favorites=favorites.includes(id)?favorites.filter(x=>x!==id):[...favorites,id];localStorage.setItem("velocity-favorites",JSON.stringify(favorites));render();toast(favorites.includes(id)?"Добавлено в избранное ♥":"Удалено из избранного");return}
 b=e.target.closest("[data-details]");if(b){showDetails(b.dataset.details);return}
 b=e.target.closest("[data-compare]");if(b){const id=+b.dataset.compare;if(compare.includes(id))compare=compare.filter(x=>x!==id);else if(compare.length>=3){toast("Можно сравнить максимум 3 автомобиля");return}else compare.push(id);render();toast("Сравнение обновлено");return}
 b=e.target.closest("[data-remove-compare]");if(b){compare=compare.filter(x=>x!==+b.dataset.removeCompare);render();return}
 b=e.target.closest("[data-modal-testdrive]");if(b){const c=cars.find(x=>x.id===+b.dataset.modalTestdrive);closeModal("modal");$("#testdriveCar").value=c?`${c.brand} ${c.name}`:"";$("#contact").scrollIntoView({behavior:"smooth"});return}
 b=e.target.closest("[data-scroll]");if(b){const el=$(b.dataset.scroll);if(el)el.scrollIntoView({behavior:"smooth"});return}
 if(e.target.id==="clearSearch")resetFilters();
});
$("#clearCompare").addEventListener("click",()=>{compare=[];render();toast("Сравнение очищено")});
$("#modalClose").addEventListener("click",()=>closeModal("modal"));$("#modal").addEventListener("click",e=>{if(e.target===$("#modal"))closeModal("modal")});
$("#adminOpen").addEventListener("click",()=>{renderAdmin();openModal("adminModal")});$("#adminClose").addEventListener("click",()=>closeModal("adminModal"));$("#adminModal").addEventListener("click",e=>{if(e.target===$("#adminModal"))closeModal("adminModal")});
$("#adminList").addEventListener("click",e=>{const b=e.target.closest("[data-admin-delete]");if(!b)return;cars=cars.filter(c=>c.id!==+b.dataset.adminDelete);saveCars();renderAdmin();render();toast("Автомобиль удалён")});
$("#addCarForm").addEventListener("submit",e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.currentTarget));const car={id:Date.now(),brand:d.brand.trim(),name:d.name.trim(),price:+d.price,power:+d.power,accel:"—",speed:0,category:"premium",tag:"NEW ARRIVAL",year:new Date().getFullYear(),drive:"—",engine:"—",image:d.image||"",desc:"Добавлено через локальную админ-панель."};cars.unshift(car);saveCars();renderAdmin();render();e.currentTarget.reset();toast("Автомобиль добавлен в каталог")});
$("#restoreCars").addEventListener("click",()=>{cars=seedCars.map(c=>({...c}));saveCars();renderAdmin();render();toast("Исходный каталог восстановлен")});
["carCost","down","term","rate"].forEach(id=>$("#"+id).addEventListener("input",calculate));
$("#financeTabs").addEventListener("click",e=>{const b=e.target.closest("[data-plan]");if(!b)return;financePlan=b.dataset.plan;$$("[data-plan]").forEach(x=>x.classList.toggle("selected",x===b));calculate()});
$("#testdriveForm").addEventListener("submit",e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.currentTarget));toast(`Спасибо, ${d.name}! Демо-заявка заполнена.`);e.currentTarget.reset()});
$("#menuToggle").addEventListener("click",()=>{const open=$("#nav").classList.toggle("open");$("#menuToggle").setAttribute("aria-expanded",String(open))});
$("#nav a").forEach(a=>a.addEventListener("click",()=>$("#nav").classList.remove("open")));
document.addEventListener("keydown",e=>{if(e.key==="Escape"){if(!$("#modal").hidden)closeModal("modal");if(!$("#adminModal").hidden)closeModal("adminModal")}});
const revealObserver=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add("visible");revealObserver.unobserve(entry.target)}}),{threshold:.12});
$$(".reveal").forEach(el=>revealObserver.observe(el));
if(!("IntersectionObserver"in window))$$(".reveal").forEach(el=>el.classList.add("visible"));
const navObserver=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting)$$(".site-header nav a").forEach(a=>a.classList.toggle("active",a.getAttribute("href")===`#${entry.target.id}`))}),{rootMargin:"-35% 0px -55% 0px"});
["home","catalog","experience","finance","about"].forEach(id=>{const el=$("#"+id);if(el)navObserver.observe(el)});
galleryInit();resetFilters();calculate();
